from google.cloud import firestore
import os

def get_firestore_client():
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable not set.")
    return firestore.Client(project=project_id)

from database_client import get_firestore_client

def upsert_document(collection_name: str, document_id: str, data: dict):
    db = get_firestore_client()
    doc_ref = db.collection(collection_name).document(document_id)
    doc_ref.set(data)
    return {"status": "success", "document_id": document_id}

from database_client import get_firestore_client

def fetch_document(collection_name: str, document_id: str):
    db = get_firestore_client()
    doc_ref = db.collection(collection_name).document(document_id)
    doc = doc_ref.get()
    if doc.exists:
        return {"status": "success", "document_id": document_id, "data": doc.to_dict()}
    else:
        return {"status": "not_found", "document_id": document_id}

from database_client import get_firestore_client

def query_documents(collection_name: str, field_name: str, field_value: any):
    db = get_firestore_client()
    query = db.collection(collection_name).where(field_name, "==", field_value).stream()
    results = []
    for doc in query:
        results.append({"document_id": doc.id, "data": doc.to_dict()})
    return {"status": "success", "results": results}

from database_client import get_firestore_client
from google.cloud.firestore import Transaction

def conditional_update(collection_name: str, document_id: str, field_to_check: str, expected_value: any, updates: dict):
    db = get_firestore_client()
    doc_ref = db.collection(collection_name).document(document_id)

    transaction = db.transaction()

    @firestore.transactional
    def update_in_transaction(transaction, doc_ref, field_to_check, expected_value, updates):
        snapshot = doc_ref.get(transaction=transaction)
        if not snapshot.exists:
            return {"status": "document_not_found", "document_id": document_id}

        if snapshot.get(field_to_check) == expected_value:
            transaction.update(doc_ref, updates)
            return {"status": "success", "document_id": document_id}
        else:
            return {"status": "condition_failed", "document_id": document_id, "current_value": snapshot.get(field_to_check)}

    return update_in_transaction(transaction, doc_ref, field_to_check, expected_value, updates)

import google.generativeai as genai
import os

def record_text_safety(text_content: str):
    genai.configure(api_key=os.getenv("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')

    # When generating content, you can set safety settings to block content that violates your policies.
    # The safety settings are set at the model level and can be configured for each request.
    # Here, we are checking for all safety categories with default thresholds.
    # This is a basic example; for production, you might refine thresholds or handle specific categories.
    try:
        response = model.generate_content(
            text_content,
            safety_settings=[
                {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
                {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
            ]
        )
        # If the response is blocked, it will raise an exception or the candidates will be empty.
        if not response._result.candidates:
            return {"status": "unsafe_content_detected", "safety_feedback": response._result.prompt_feedback}
        else:
            return {"status": "safe_content", "safety_feedback": response._result.prompt_feedback}
    except Exception as e:
        # This might catch cases where the prompt itself is blocked before content generation
        return {"status": "error_checking_safety", "details": str(e)}
